def card(item):
 id=item['id'];label=item['label'];group=item['group'];n=item['number']
 if group=='pictures':top=f'<h3>Picture <span class="pr-original-number">{n}</span></h3><figure class="pr-original-photo"><img src="{MEDIA+item["image"]}" width="{item["width"]}" height="{item["height"]}" alt="{escape(item["alt"])}" loading="lazy"><figcaption>ESL Pals · Original picture {n}</figcaption></figure>'
