 body=f'<article class="pr-card" id="pr-item-{id}" data-pr-item="{id}">{top}<label for="pr-notes-{id}">Notes for {label} · optional</label><textarea id="pr-notes-{id}" rows="4" spellcheck="true" aria-describedby="pr-feedback-{id}" placeholder="Optional: prepare words or ideas for your speaking turn."></textarea><div class="pr-checks">'
 for i,text in enumerate(SELF_CHECK[group]):body+=f'<label><input type="checkbox" data-pr-check="{i}"> <span>{escape(text)}</span></label>'
 return body+f'</div><div class="pi-actions"><button type="button" class="btn btn-primary" data-pr-review>Review {label}</button><button type="button" class="btn btn-secondary" data-pr-reset>Start {label} again</button><button type="button" class="btn btn-secondary" data-pr-undo hidden>Undo reset {label}</button></div><p class="pr-feedback" id="pr-feedback-{id}" role="status" aria-live="polite" tabindex="-1" hidden></p></article>'
